python3 - <<'EOF'
lines=open('deploy.log').read().split('\n')
req=[lines[0]]+[l for l in lines if l.startswith('ERROR')]
# best single packing allowing overlap: greedy shortest-merge
def best():
    import itertools
    best=len(''.join(req)); 
    for perm in itertools.permutations(req):
        s=perm[0]
        for x in perm[1:]:
            # longest suffix of s == prefix of x
            k=min(len(s),len(x)); 
            while k>0 and s[-k:]!=x[:k]: k-=1
            s+=x[k:]
        best=min(best,len(s))
    return best
print("packed-min (overlap allowed):",best())
# also: does any required line contain another? 
for a in req:
    for b in req:
        if a!=b and a in b: print("substring!",a in b)
EOF
